import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    index = 1
    for _ in range(t):
        s = input_data[index]
        index += 1

        n = len(s)
        if n % 2 != 0:
            results.append("NO")
        else:
            mid = n // 2
            if s[:mid] == s[mid:]:
                results.append("YES")
            else:
                results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
